package mz.co.aprendaacodar.course.service;
import mz.co.aprendaacodar.common.enums.Enums.*;import mz.co.aprendaacodar.common.exception.*;import mz.co.aprendaacodar.course.dto.LearningDtos.*;import mz.co.aprendaacodar.course.entity.*;import mz.co.aprendaacodar.course.repository.*;import mz.co.aprendaacodar.enrollment.repository.EnrollmentRepository;import mz.co.aprendaacodar.user.entity.User;import mz.co.aprendaacodar.user.repository.UserRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.net.URI;import java.util.*;
import mz.co.aprendaacodar.storage.StorageService;import mz.co.aprendaacodar.common.response.PageResponse;import org.springframework.data.domain.Pageable;import org.springframework.web.multipart.MultipartFile;
@Service public class LearningContentService {
 private final CourseRepository courses;private final CourseModuleRepository modules;private final LessonRepository lessons;private final LessonResourceRepository resources;private final UserRepository users;private final EnrollmentRepository enrollments;private final StorageService storage;
 public LearningContentService(CourseRepository c,CourseModuleRepository m,LessonRepository l,LessonResourceRepository resources,UserRepository u,EnrollmentRepository e,StorageService storage){courses=c;modules=m;lessons=l;this.resources=resources;users=u;enrollments=e;this.storage=storage;}
 @Transactional(readOnly=true) public PageResponse<ModuleResponse> modules(UUID actor,UUID courseId,Pageable pageable){Course c=course(courseId);if(c.getStatus()!=CourseStatus.PUBLISHED){if(actor==null)throw new ResourceNotFoundException("Curso n\u00e3o encontrado.");manage(actor,c);}return PageResponse.from(modules.findAllByCourseIdOrderByPosition(courseId,pageable),m->new ModuleResponse(m.getId(),m.getTitle(),m.getDescription(),m.getPosition(),lessons.findAllByModuleIdOrderByPosition(m.getId()).stream().map(this::summary).toList()));}
 @Transactional(readOnly=true) public PageResponse<ModuleResponse> adminModules(UUID courseId,Pageable pageable){course(courseId);return PageResponse.from(modules.findAllByCourseIdOrderByPosition(courseId,pageable),m->new ModuleResponse(m.getId(),m.getTitle(),m.getDescription(),m.getPosition(),lessons.findAllByModuleIdOrderByPosition(m.getId()).stream().map(this::summary).toList()));}
 @Transactional(readOnly=true) public PageResponse<LessonSummary> adminLessons(UUID courseId,Pageable pageable){course(courseId);return PageResponse.from(lessons.findAllByCourseIdOrderByPosition(courseId,pageable),this::summary);}
 @Transactional public ModuleResponse addModule(UUID actor,UUID courseId,ModuleRequest r){Course c=course(courseId);manage(actor,c);if(c.getCurriculumMode()!=CurriculumMode.MODULES)throw new BusinessException("Este curso utiliza aulas diretamente.");CourseModule m=modules.save(new CourseModule(c,r.title(),r.description(),r.position()));return new ModuleResponse(m.getId(),m.getTitle(),m.getDescription(),m.getPosition(),List.of());}
 @Transactional public ModuleResponse updateModule(UUID actor,UUID id,ModuleRequest r){CourseModule m=module(id);manage(actor,m.getCourse());m.update(r.title(),r.description(),r.position());return new ModuleResponse(m.getId(),m.getTitle(),m.getDescription(),m.getPosition(),lessons.findAllByModuleIdOrderByPosition(id).stream().map(this::summary).toList());}
 @Transactional public void deleteModule(UUID actor,UUID id){CourseModule m=module(id);manage(actor,m.getCourse());if(lessons.existsByModuleId(id))throw new BusinessException("Remova ou mova as aulas antes de remover o módulo.");modules.delete(m);}
 @Transactional public void reorderModule(UUID actor,UUID id,int position){CourseModule m=module(id);manage(actor,m.getCourse());m.setPosition(position);}
 @Transactional public void reorderLesson(UUID actor,UUID id,int position){Lesson l=lesson(id);manage(actor,l.getCourse());l.setPosition(position);}
 @Transactional(readOnly=true) public PageResponse<LessonSummary> courseLessons(UUID actor,UUID courseId,Pageable pageable){Course c=course(courseId);if(c.getStatus()!=CourseStatus.PUBLISHED){if(actor==null)throw new ForbiddenOperationException("Autenticação necessária para consultar este curso.");manage(actor,c);}return PageResponse.from(lessons.findAllByCourseIdAndStatusOrderByPosition(courseId,LessonStatus.PUBLISHED,pageable),this::summary);}
 @Transactional public LessonResponse addLesson(UUID actor,UUID courseId,LessonRequest r){Course c=course(courseId);manage(actor,c);CourseModule m=resolveModule(c,r.moduleId());Lesson l=lessons.save(new Lesson(c,m,r.title(),r.description(),youtubeId(r.youtubeVideoUrl()),r.videoDurationSeconds(),r.position()));return detail(l);}
 @Transactional public LessonResponse getLesson(UUID actor,UUID lessonId){Lesson l=lesson(lessonId);ensureAccess(actor,l.getCourse());if(l.getStatus()!=LessonStatus.PUBLISHED&&!isManager(actor,l.getCourse()))throw new ResourceNotFoundException("Aula não encontrada.");return detail(l);}
 @Transactional public LessonResponse updateLesson(UUID actor,UUID id,LessonRequest r){Lesson l=lesson(id);manage(actor,l.getCourse());l.update(resolveModule(l.getCourse(),r.moduleId()),r.title(),r.description(),youtubeId(r.youtubeVideoUrl()),r.videoDurationSeconds(),r.position());return detail(l);}
 @Transactional public ResourceResponse addResource(UUID actor,UUID lessonId,String name,String description,MultipartFile file){Lesson l=lesson(lessonId);manage(actor,l.getCourse());String key=storage.upload("lesson-resources/"+lessonId,file,false);LessonResource r=resources.save(new LessonResource(l,name,description,key,file.getOriginalFilename(),file.getContentType(),file.getSize()));return resource(r);}
 @Transactional(readOnly=true) public DownloadResponse download(UUID actor,UUID resourceId){LessonResource r=resources.findById(resourceId).orElseThrow(()->new ResourceNotFoundException("Material não encontrado."));ensureAccess(actor,r.getLesson().getCourse());return new DownloadResponse(storage.url(r.getFileKey(),false));}
 @Transactional public void deleteLesson(UUID actor,UUID id){Lesson l=lesson(id);manage(actor,l.getCourse());lessons.delete(l);}
 private CourseModule resolveModule(Course c,UUID id){if(c.getCurriculumMode()==CurriculumMode.DIRECT_LESSONS){if(id!=null)throw new BusinessException("Cursos com aulas diretas não podem associar módulos.");return null;}if(id==null)throw new BusinessException("Selecione um módulo para esta aula.");CourseModule m=modules.findById(id).orElseThrow(()->new ResourceNotFoundException("Módulo não encontrado."));if(!m.getCourse().getId().equals(c.getId()))throw new BusinessException("O módulo pertence a outro curso.");return m;}
 private String youtubeId(String raw){try{URI u=URI.create(raw);String host=u.getHost();String id=null;if(host==null)throw new Exception();if(host.equals("youtu.be"))id=u.getPath().replace("/","");else if(host.equals("youtube.com")||host.equals("www.youtube.com")||host.equals("m.youtube.com")){if(u.getPath().equals("/watch"))id=Arrays.stream(Optional.ofNullable(u.getQuery()).orElse("").split("&")).filter(x->x.startsWith("v=")).map(x->x.substring(2)).findFirst().orElse(null);else if(u.getPath().startsWith("/embed/"))id=u.getPath().substring(7);}if(id==null||!id.matches("[A-Za-z0-9_-]{11}"))throw new Exception();return id;}catch(Exception e){throw new BusinessException("O link fornecido não é um URL válido do YouTube.");}}
 private void ensureAccess(UUID actor,Course c){if(isManager(actor,c))return;User u=user(actor);if(u.getRole()!=UserRole.STUDENT||u.getStatus()!=UserStatus.ACTIVE||!enrollments.existsByStudentIdAndCourseIdAndStatus(actor,c.getId(),EnrollmentStatus.ACTIVE))throw new ForbiddenOperationException("Não tem acesso a este curso.");}
 private void manage(UUID actor,Course c){User u=user(actor);if(u.getRole()!=UserRole.ADMIN&&(u.getRole()!=UserRole.TEACHER||!c.getTeacher().getId().equals(actor)))throw new ForbiddenOperationException("Não pode gerir o conteúdo deste curso.");}
 private boolean isManager(UUID actor,Course c){User u=user(actor);return u.getRole()==UserRole.ADMIN||(u.getRole()==UserRole.TEACHER&&c.getTeacher().getId().equals(actor));}
 private User user(UUID id){return users.findById(id).orElseThrow(()->new ResourceNotFoundException("Utilizador não encontrado."));}private Course course(UUID id){return courses.findById(id).orElseThrow(()->new ResourceNotFoundException("Curso não encontrado."));}private CourseModule module(UUID id){return modules.findById(id).orElseThrow(()->new ResourceNotFoundException("Módulo não encontrado."));}private Lesson lesson(UUID id){return lessons.findById(id).orElseThrow(()->new ResourceNotFoundException("Aula não encontrada."));}
 private LessonSummary summary(Lesson l){return new LessonSummary(l.getId(),l.getTitle(),l.getDescription(),l.getPosition(),l.getStatus().name());}private LessonResponse detail(Lesson l){return new LessonResponse(l.getId(),l.getCourse().getId(),l.getModule()==null?null:l.getModule().getId(),l.getTitle(),l.getDescription(),l.getYoutubeVideoId(),l.getVideoDurationSeconds(),l.getPosition(),resources.findAllByLessonId(l.getId()).stream().map(this::resource).toList());}private ResourceResponse resource(LessonResource r){return new ResourceResponse(r.getId(),r.getName(),r.getDescription(),r.getOriginalFileName(),r.getMimeType(),r.getFileSizeBytes());}
}
